# file binary data formats - This list is generated by claude, everything else is written by me
# CAMERAS.BIN, per camera:
#   camera_id
#   model_id
#   width
#   height
#   params (fx, fy, cx, cy for PINHOLE; f, cx, cy for SIMPLE_PINHOLE)

# IMAGES.BIN, per image:
#   image_id
#   quaternion (qw, qx, qy, qz)
#   translation (tx, ty, tz)
#   camera_id
#   name
#   number of keypoints
#   keypoints (skip)

# POINTS3D.BIN, per point:
#   point3D_id
#   position (x, y, z)
#   color (r, g, b)
#   error (skip)
#   track length
#   track (skip)


import struct
from pathlib import Path

# the parameters corresponding to a given camera model 
CAMERA_MODEL_PARAMS = {
    0: 3,   # SIMPLE_PINHOLE: f, cx, cy
    1: 4,   # PINHOLE: fx, fy, cx, cy
    2: 4,   # SIMPLE_RADIAL: f, cx, cy, k
    3: 5,   # RADIAL: f, cx, cy, k1, k2
    4: 8,   # OPENCV: fx, fy, cx, cy, k1, k2, p1, p2
    5: 8,   # OPENCV_FISHEYE: fx, fy, cx, cy, k1, k2, k3, k4
    6: 12,  # FULL_OPENCV: fx, fy, cx, cy, k1, k2, p1, p2, k3, k4, k5, k6
    7: 5,   # FOV: fx, fy, cx, cy, omega
    8: 4,   # SIMPLE_RADIAL_FISHEYE: f, cx, cy, k
    9: 5,   # RADIAL_FISHEYE: f, cx, cy, k1, k2
    10: 12  # THIN_PRISM_FISHEYE: fx, fy, cx, cy, k1, k2, p1, p2, k3, k4, sx1, sy1
}

########################################################################################################################
# Camera Data
########################################################################################################################
def read_camera_data(camera_file: Path):
    """
    Read camera data from a COLMAP binary file.
    Args:
        camera_file: Path to the cameras.bin file.
    Returns:
        A dictionary mapping camera IDs to their corresponding data,
        including model ID, width, height, and any additional parameters.
    """
    if not camera_file.exists():
        raise FileNotFoundError(f"File not found: {str(camera_file)}")

    # buffer and offset for reading binary data
    camera_buf = camera_file.read_bytes()
    camera_off = 0

    camera_fmt = "<iiQQ"                          # camera_id, model_id, width, height
    camera_size = struct.calcsize(camera_fmt)           # 4 + 4 + 8 + 8 = 24
    camera_count = struct.unpack_from("<Q", camera_buf, camera_off)[0]  # number of cameras
    camera_off += 8

    # dict to hold unpacked data
    cameras = {}

    for _ in range(camera_count):
        camera_id, model_id, width, height = struct.unpack_from(camera_fmt, camera_buf, camera_off)
        camera_off += camera_size

        # get the number of parameters for this camera model
        num_params = CAMERA_MODEL_PARAMS.get(model_id)
        if num_params is None:
            raise ValueError(f"Unknown camera model ID: {model_id}")

        # read the parameters
        params_camera_fmt = f"<{num_params}d"  # double precision floats
        params_size = struct.calcsize(params_camera_fmt)
        params = struct.unpack_from(params_camera_fmt, camera_buf, camera_off)
        camera_off += params_size

        # store in dict
        cameras[camera_id] = {
            "model_id": model_id,
            "width": width,
            "height": height,
            "params": params,
        }

    if camera_off != len(camera_buf):
        raise ValueError(f"Camera offset is {camera_off} bytes but the buffer is {len(camera_buf)} bytes")

    return cameras


########################################################################################################################
# Image Data
########################################################################################################################
def read_image_data(image_file: Path):
    """
    Read image data from a COLMAP binary file.
    Args:
        image_file: Path to the images.bin file.
    Returns:
        A dictionary mapping image IDs to their corresponding data, including quaternion, 
        translation, camera ID, name, and number of keypoints (but not the keypoints themselves).
    """

    if not image_file.exists():
        raise FileNotFoundError(f"File not found: {str(image_file)}") 

    image_off = 0

    image_fmt = "<IdddddddI"  # image_id, qw, qx, qy, qz, tx, ty, tz, camera_id
    image_buf = image_file.read_bytes()
    image_count = struct.unpack_from("<Q", image_buf, 0)[0]  # number of images
    image_off += 8

    # image dict to hold unpacked data
    images = {}

    for _ in range(image_count):
        image_id, qw, qx, qy, qz, tx, ty, tz, camera_id = struct.unpack_from(image_fmt, image_buf, image_off)
        image_off += struct.calcsize(image_fmt)

        # read the image name
        name_end = image_buf.index(b"\x00", image_off)  # find null terminator
        name = image_buf[image_off:name_end].decode("utf-8")  # decode to string
        image_off = name_end + 1  # move offset past null terminator

        # read number of keypoints (skip keypoints themselves)
        num_keypoints = struct.unpack_from("<Q", image_buf, image_off)[0]
        image_off += 8 + num_keypoints * 24  # skip keypoints (2 doubles and a int64 per keypoint)

        # store in dict
        images[image_id] = {
            "quaternion": (qw, qx, qy, qz),
            "translation": (tx, ty, tz),
            "camera_id": camera_id,
            "name": name,
            "num_keypoints": num_keypoints,
        }

    if image_off != len(image_buf):
        raise ValueError(f"Image offset is {image_off} bytes but the buffer is {len(image_buf)} bytes")

    return images

########################################################################################################################
# Point3D Data
########################################################################################################################
# read point3D data from binary file
def read_point3D_data(point3D_file: Path):
    """
    Read point3D data from a COLMAP binary file.
    Args:
        point3D_file: Path to the points3D.bin file.
    Returns:
        A dictionary mapping point3D IDs to their corresponding data,
        including position, color, and track length.
    """

    if not point3D_file.exists():
        raise FileNotFoundError(f"File not found: {str(point3D_file)}") 

    point3D_off = 0

    point3D_fmt = "<QdddBBBdQ"  # point3D_id, x, y, z, r, g, b, error, track_length
    point3D_buf = point3D_file.read_bytes()
    point3D_count = struct.unpack_from("<Q", point3D_buf, 0)[0]  # number of points3D
    point3D_off += 8

    # point3D dict to hold unpacked data
    points3D = {}

    for _ in range(point3D_count):
        point3D_id, x, y, z, r, g, b, error, track_length = struct.unpack_from(point3D_fmt, point3D_buf, point3D_off)
        point3D_off += struct.calcsize(point3D_fmt)

        # skip the track (2 * track_length * 4 bytes)
        point3D_off += track_length * 2 * 4

        # we also skip error and track data, as they are not needed for our purposes
        
        # error just measures how confident the colmap reconstruction is, but splatting
        # just doesn't need that info

        # store in dict
        points3D[point3D_id] = {
            "position": (x, y, z),
            "color": (r, g, b),
            "track_length": track_length,
        }

    if point3D_off != len(point3D_buf):
        raise ValueError(f"Point3D offset is {point3D_off} bytes but the buffer is {len(point3D_buf)} bytes")

    return points3D



if __name__ == "__main__":
    # paths to the binary files for the bonsai dataset
    camera_path = Path(__file__).parent.parent.parent.parent / "data" / "mipnerf360" / "bonsai" / "sparse/0" / "cameras.bin"
    image_path = Path(__file__).parent.parent.parent.parent / "data" / "mipnerf360" / "bonsai" / "sparse/0" / "images.bin"
    point3D_path = Path(__file__).parent.parent.parent.parent / "data" / "mipnerf360" / "bonsai" / "sparse/0" / "points3D.bin"
    # calling methods to read the data
    cameras = read_camera_data(camera_path)
    images = read_image_data(image_path)
    points3D = read_point3D_data(point3D_path)